import "./chart.css";

const LanguagesChart = () => {
  return (
    <div className="languages-container">
      <div className="chart-card">
        <h3 className="chart-title">Languages Used</h3>
        <div className="chart-placeholder">
          <p>[Pie Chart]</p>
        </div>
      </div>
    </div>
  );
};

export default LanguagesChart;
